	_ = s.recomputeServiceabilitySnapshot(ctx, s.db)
	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "update_location", "location", locID.String(), true, time.Now().UTC(), map[string]any{"name": *req.Name})
	s.publishEvent(ctx, s.db, "location_updated", "location", locID.String(), map[string]any{"locationId": locID.String()})

	writeData(w, 201, Location{
		LocationID:      locID.String(),
		Name:            *req.Name,
		Coordinate:      *req.Coordinate,
		CoverageKm:      curCov,
		HandlingMinutes: curHand,
		Active:          curActive,
		Functions:       fnStates,
	})
}

