	}
	if req.RequiredQualification != nil {
		cur.RequiredQualification = *req.RequiredQualification
	}
	cur.ContainerType = container
	cur.TemperatureMinC = *req.TemperatureMinC
	cur.TemperatureMaxC = *req.TemperatureMaxC
	if req.IncompatibleSampleTypes != nil {
		cur.IncompatibleSampleTypes = *req.IncompatibleSampleTypes
	}
	if req.RequiresCooledRoute != nil {
