		SET qualified_collector_required = $1, required_qualification = $2, container_type = $3,
		    temperature_min_c = $4, temperature_max_c = $5, incompatible_sample_types = $6,
		    requires_cooled_route = $7, batching_allowed = $8
		WHERE sample_type_id = $9
	`, cur.QualifiedCollectorRequired, cur.RequiredQualification, cur.ContainerType,
		cur.TemperatureMinC, cur.TemperatureMaxC, incB, cur.RequiresCooledRoute, cur.BatchingAllowed, stID)
	if err != nil {
