	_ = s.recomputeServiceabilitySnapshot(ctx, s.db)
	s.recordAudit(ctx, s.db, auth.UserID.String(), auth.ActiveRole, "update_sample_type", "sample_type", stID.String(), true, time.Now().UTC(), map[string]any{"sampleTypeId": stID.String()})

